\set ON_ERROR_STOP on
-- Disposable PostgreSQL fixture only: tests exact reviewed ACL SQL, not full legacy business implementation.
create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
grant usage on schema auth to authenticated;
create table public.users(id uuid primary key, role text, status text, balance numeric);
insert into public.users values ('00000000-0000-0000-0000-000000000001','admin','active',0),('00000000-0000-0000-0000-000000000002','user','active',0);
alter table public.users enable row level security;
grant select on public.users to authenticated,service_role;
create policy own_user on public.users for select to authenticated using(id=auth.uid());
create table public.seller_subscriptions(id int primary key,status text);
insert into public.seller_subscriptions values (1,'historical');
create table public.wallet_transactions(id int primary key,amount numeric);
insert into public.wallet_transactions values(1,10);
create table public.cardora_community_snapshot(singleton boolean,registered_members bigint);
insert into public.cardora_community_snapshot values(true,7);
alter table public.cardora_community_snapshot enable row level security;
grant select on public.cardora_community_snapshot to anon,authenticated;
create policy stats_read on public.cardora_community_snapshot for select to anon,authenticated using(singleton);
create table public.cardora_member_details(owner_id uuid primary key,nickname text);
alter table public.cardora_member_details enable row level security;
grant select,insert,update on public.cardora_member_details to authenticated;
create policy own_details on public.cardora_member_details to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create table public.legacy_calls(name text);
create function public.admin_get_listing_review_queue(integer) returns boolean language sql security definer set search_path='' as $$select true$$;
create function public.admin_review_listing(uuid,text,text) returns boolean language sql security definer set search_path='' as $$insert into public.legacy_calls values('listing') returning true$$;
create function public.admin_review_seller_application(uuid,text,text) returns boolean language sql security definer set search_path='' as $$insert into public.legacy_calls values('application') returning true$$;
create function public.seller_subscription_summary() returns boolean language sql security definer set search_path='' as $$select true$$;
revoke execute on function public.admin_get_listing_review_queue(integer),public.admin_review_listing(uuid,text,text),public.admin_review_seller_application(uuid,text,text),public.seller_subscription_summary() from public,anon;
grant execute on function public.admin_get_listing_review_queue(integer),public.admin_review_listing(uuid,text,text),public.admin_review_seller_application(uuid,text,text),public.seller_subscription_summary() to authenticated,service_role;
create temp table baseline as select oid,pg_get_functiondef(oid) definition,proowner,prosecdef,proconfig from pg_proc where oid in ('public.admin_get_listing_review_queue(integer)'::regprocedure,'public.admin_review_listing(uuid,text,text)'::regprocedure,'public.admin_review_seller_application(uuid,text,text)'::regprocedure,'public.seller_subscription_summary()'::regprocedure);
create schema test_only;
grant usage on schema test_only to authenticated,anon,service_role;
create function test_only.ok(v boolean,label text) returns void language plpgsql security invoker as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function test_only.denied(q text,label text) returns void language plpgsql security invoker as $$begin begin execute q;exception when insufficient_privilege then raise notice 'PASS: % (42501)',label;return;end;raise exception 'FAIL: % unexpectedly succeeded',label;end$$;
select test_only.ok((select bool_and(has_function_privilege('authenticated',oid,'EXECUTE')) from baseline),'fixture reproduces original grants');
\ir ../docs/security/legacy-commercial-isolation-review.sql
select test_only.ok((select bool_and(not has_function_privilege('anon',oid,'EXECUTE') and not has_function_privilege('authenticated',oid,'EXECUTE') and has_function_privilege('service_role',oid,'EXECUTE')) from baseline),'all four ACLs isolated, service role retained');
select test_only.ok((select bool_and(pg_get_functiondef(b.oid)=b.definition and p.proowner=b.proowner and p.prosecdef=b.prosecdef and p.proconfig=b.proconfig) from baseline b join pg_proc p using(oid)),'function definitions and owners unchanged');
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select test_only.denied('select public.admin_get_listing_review_queue(1)','ordinary member queue blocked');
select test_only.denied($q$select public.admin_review_listing(null,'active',null)$q$,'ordinary member listing review blocked');
select test_only.denied($q$select public.admin_review_seller_application(null,'approved',null)$q$,'ordinary member application review blocked');
select test_only.denied('select public.seller_subscription_summary()','ordinary member subscription summary blocked');
select test_only.ok((select role='user' from public.users),'member account still readable');
insert into public.cardora_member_details values(auth.uid(),'synthetic nickname');
select test_only.ok((select nickname='synthetic nickname' from public.cardora_member_details),'own profile write unaffected');
select test_only.ok((select registered_members=7 from public.cardora_community_snapshot),'member statistics unaffected');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select test_only.ok((select role='admin' and status='active' from public.users),'admin identity and status unaffected');
select test_only.denied('select public.admin_get_listing_review_queue(1)','admin old queue deliberately blocked');
select test_only.denied($q$select public.admin_review_listing(null,'active',null)$q$,'admin old listing review deliberately blocked');
select test_only.denied($q$select public.admin_review_seller_application(null,'approved',null)$q$,'admin old application review deliberately blocked');
select test_only.denied('select public.seller_subscription_summary()','admin old subscription query deliberately blocked');
reset role;
set role anon;
select test_only.denied('select public.admin_get_listing_review_queue(1)','guest queue blocked');
select test_only.denied($q$select public.admin_review_listing(null,'active',null)$q$,'guest listing review blocked');
select test_only.denied($q$select public.admin_review_seller_application(null,'approved',null)$q$,'guest application review blocked');
select test_only.denied('select public.seller_subscription_summary()','guest subscription summary blocked');
select test_only.ok((select registered_members=7 from public.cardora_community_snapshot),'public stats unaffected');
reset role;
set role service_role;
select test_only.ok((select count(*)=2 from public.users),'admin overview service-role fixture still reads members');
select test_only.ok(public.admin_get_listing_review_queue(1),'preserved service role can execute sentinel read function');
reset role;
select test_only.ok((select count(*)=0 from public.legacy_calls),'no blocked mutation ran');
select test_only.ok((select count(*)=1 and bool_and(status='historical') from public.seller_subscriptions),'historical subscription untouched');
select test_only.ok((select count(*)=1 and sum(amount)=10 from public.wallet_transactions),'wallet history untouched');
-- A deliberately simulated restore confirms reversibility without changing any production ACL.
begin;
grant execute on function public.admin_get_listing_review_queue(integer),public.admin_review_listing(uuid,text,text),public.admin_review_seller_application(uuid,text,text),public.seller_subscription_summary() to authenticated;
select test_only.ok((select bool_and(has_function_privilege('authenticated',oid,'EXECUTE')) from baseline),'isolated rollback rehearsal');
rollback;
select test_only.ok((select bool_and(not has_function_privilege('authenticated',oid,'EXECUTE')) from baseline),'test ends isolated');
\echo 'ALL LEGACY COMMERCIAL ACL TESTS PASSED'
